ST.xhtml:p:
(*检测碰板*)
IF g_nCalStatus=0 THEN
  IF bPreTouchEnable THEN
    IF g_fZAxisHeight <= dPreTouchHeight OR g_biPresterPanelSignal THEN
      IF g_niMotionType=1 THEN
        Timer_G00(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(dTouchDelayTimeG00)));
      ELSIF g_nPiercingStatus=1 THEN
        Timer_Piercing(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(dTouchDelayTimePiercing)));
      ELSE
        Timer_Cutting(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(dTouchDelayTimeCutting)));
      END_IF;

      IF Timer_G00.Q OR Timer_Piercing.Q OR Timer_Cutting.Q THEN
        g_bTouchPanel := TRUE;
        Timer_G00(IN := FALSE);
        Timer_Cutting(IN := FALSE);
        Timer_Piercing(IN := FALSE);
      END_IF;
    ELSE
      Timer_G00(IN := FALSE);
      Timer_Cutting(IN := FALSE);
      Timer_Piercing(IN := FALSE);
      g_bTouchPanel := FALSE;
    END_IF;
  ELSE
    IF (g_niZSensorValue <= g_nSensorDown) OR g_biPresterPanelSignal THEN
      IF g_niMotionType=1 THEN
        Timer_G00(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(dTouchDelayTimeG00)));
      ELSIF g_nPiercingStatus=1 THEN
        Timer_Piercing(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(dTouchDelayTimePiercing)));
      ELSE
        Timer_Cutting(IN := TRUE,PT := LREAL_TO_TIME(FUN_MStoS(dTouchDelayTimeCutting)));
      END_IF;

      IF Timer_G00.Q OR Timer_Piercing.Q OR Timer_Cutting.Q THEN
        g_bTouchPanel := TRUE;
        Timer_G00(IN := FALSE);
        Timer_Cutting(IN := FALSE);
        Timer_Piercing(IN := FALSE);
      END_IF;
    ELSE
      Timer_G00(IN := FALSE);
      Timer_Cutting(IN := FALSE);
      Timer_Piercing(IN := FALSE);
      g_bTouchPanel := FALSE;
    END_IF;
  END_IF;
END_IF;
IF g_bResetCurHeight  OR g_bHmiCloseFollow THEN(*重置本体电容，碰板报警不报*)
  g_bTouchPanel := FALSE;
END_IF;
